from pathlib import Path

p = Path("app/src/main/java/com/seolhwa/armyrist/MainActivity.kt")
s = p.read_text(encoding="utf-8")

anchor = "import androidx.compose.foundation.layout.*\n"
extra = "import androidx.compose.foundation.rememberScrollState\nimport androidx.compose.foundation.verticalScroll\nimport androidx.compose.ui.window.Dialog\n"
if "import androidx.compose.foundation.rememberScrollState" not in s:
    s = s.replace(anchor, anchor + extra, 1)

start = s.index("@Composable\nprivate fun CalculationDialog(")
end = s.index("\nprivate val GROUP_COLORS", start)

replacement = '@OptIn(ExperimentalLayoutApi::class)\n@Composable\nprivate fun CalculationDialog(\n    sheet: CountingSheet,\n    current: GroupCalculation?,\n    done: (CalcDraft?) -> Unit\n) {\n    if (sheet.groups.isEmpty()) {\n        done(null)\n        return\n    }\n\n    var left by remember { mutableStateOf(current?.leftGroupId ?: sheet.groups.first().id) }\n    var right by remember { mutableStateOf(current?.rightGroupId ?: sheet.groups.first().id) }\n    var operator by remember { mutableStateOf(current?.operator ?: CalculationOperator.ADD) }\n    var name by remember { mutableStateOf(current?.name ?: "") }\n\n    Dialog(onDismissRequest = { done(null) }) {\n        Surface(\n            modifier = Modifier.fillMaxWidth().heightIn(max = 680.dp),\n            shape = ArmyristPanelShape,\n            color = ArmyristColors.WorkSurface,\n            contentColor = ArmyristColors.PrimaryText,\n            border = BorderStroke(1.dp, ArmyristColors.Border)\n        ) {\n            Column(Modifier.fillMaxWidth()) {\n                Column(\n                    Modifier.fillMaxWidth()\n                        .background(ArmyristColors.RaisedSurface)\n                        .padding(horizontal = 18.dp, vertical = 14.dp)\n                ) {\n                    Text(\n                        if (current == null) "계산 추가" else "계산 편집",\n                        style = MaterialTheme.typography.titleLarge,\n                        fontWeight = FontWeight.Bold\n                    )\n                    Text(\n                        "COUNTING · CALCULATION",\n                        style = MaterialTheme.typography.labelSmall,\n                        color = ArmyristColors.SecondaryText\n                    )\n                }\n\n                HorizontalDivider(color = ArmyristColors.Divider)\n\n                Column(\n                    modifier = Modifier\n                        .weight(1f, fill = false)\n                        .verticalScroll(rememberScrollState())\n                        .padding(horizontal = 18.dp, vertical = 12.dp),\n                    verticalArrangement = Arrangement.spacedBy(12.dp)\n                ) {\n                    ArmyristSectionLabel("왼쪽 그룹")\n                    CalculationGroupChoices(\n                        groups = sheet.groups.sortedBy { it.order },\n                        selectedId = left,\n                        onSelect = { left = it }\n                    )\n\n                    HorizontalDivider(color = ArmyristColors.Divider)\n\n                    ArmyristSectionLabel("연산")\n                    FlowRow(\n                        modifier = Modifier.fillMaxWidth(),\n                        horizontalArrangement = Arrangement.spacedBy(8.dp),\n                        verticalArrangement = Arrangement.spacedBy(8.dp)\n                    ) {\n                        ArmyristChoiceChip(\n                            text = "+",\n                            selected = operator == CalculationOperator.ADD,\n                            onClick = { operator = CalculationOperator.ADD }\n                        )\n                        ArmyristChoiceChip(\n                            text = "−",\n                            selected = operator == CalculationOperator.SUBTRACT,\n                            onClick = { operator = CalculationOperator.SUBTRACT }\n                        )\n                    }\n\n                    HorizontalDivider(color = ArmyristColors.Divider)\n\n                    ArmyristSectionLabel("오른쪽 그룹")\n                    CalculationGroupChoices(\n                        groups = sheet.groups.sortedBy { it.order },\n                        selectedId = right,\n                        onSelect = { right = it }\n                    )\n\n                    OutlinedTextField(\n                        value = name,\n                        onValueChange = { name = it },\n                        label = { Text("계산명 (선택)") },\n                        singleLine = true,\n                        modifier = Modifier.fillMaxWidth(),\n                        colors = OutlinedTextFieldDefaults.colors(\n                            focusedContainerColor = ArmyristColors.InputSurface,\n                            unfocusedContainerColor = ArmyristColors.InputSurface,\n                            focusedBorderColor = ArmyristColors.PrimaryControl,\n                            unfocusedBorderColor = ArmyristColors.Border\n                        )\n                    )\n                }\n\n                HorizontalDivider(color = ArmyristColors.Divider)\n\n                Row(\n                    modifier = Modifier.fillMaxWidth()\n                        .background(ArmyristColors.RaisedSurface)\n                        .padding(horizontal = 12.dp, vertical = 10.dp),\n                    horizontalArrangement = Arrangement.End,\n                    verticalAlignment = Alignment.CenterVertically\n                ) {\n                    OutlinedButton(\n                        onClick = { done(null) },\n                        shape = ArmyristPanelShape,\n                        border = BorderStroke(1.dp, ArmyristColors.Border),\n                        colors = ButtonDefaults.outlinedButtonColors(\n                            containerColor = ArmyristColors.WorkSurface,\n                            contentColor = ArmyristColors.PrimaryText\n                        )\n                    ) { Text("취소") }\n\n                    Spacer(Modifier.width(8.dp))\n\n                    Button(\n                        onClick = {\n                            done(CalcDraft(left, operator, right, name.trim()))\n                        },\n                        shape = ArmyristPanelShape,\n                        colors = ButtonDefaults.buttonColors(\n                            containerColor = ArmyristColors.PrimaryControl,\n                            contentColor = ArmyristColors.OnDark\n                        )\n                    ) { Text("확인", fontWeight = FontWeight.Bold) }\n                }\n            }\n        }\n    }\n}\n\n@OptIn(ExperimentalLayoutApi::class)\n@Composable\nprivate fun CalculationGroupChoices(\n    groups: List<CountingGroup>,\n    selectedId: String,\n    onSelect: (String) -> Unit\n) {\n    FlowRow(\n        modifier = Modifier.fillMaxWidth(),\n        horizontalArrangement = Arrangement.spacedBy(7.dp),\n        verticalArrangement = Arrangement.spacedBy(7.dp)\n    ) {\n        groups.forEach { group ->\n            ArmyristChoiceChip(\n                text = group.name,\n                selected = selectedId == group.id,\n                onClick = { onSelect(group.id) }\n            )\n        }\n    }\n}\n\n@Composable\nprivate fun ArmyristChoiceChip(\n    text: String,\n    selected: Boolean,\n    onClick: () -> Unit\n) {\n    Surface(\n        onClick = onClick,\n        shape = ArmyristPanelShape,\n        color = if (selected) ArmyristColors.PrimaryControl else ArmyristColors.RaisedSurface,\n        contentColor = if (selected) ArmyristColors.OnDark else ArmyristColors.PrimaryText,\n        border = BorderStroke(\n            if (selected) 2.dp else 1.dp,\n            if (selected) ArmyristColors.Accent else ArmyristColors.Border\n        )\n    ) {\n        Text(\n            text = text,\n            modifier = Modifier.padding(horizontal = 12.dp, vertical = 9.dp),\n            fontWeight = if (selected) FontWeight.Bold else FontWeight.Medium,\n            maxLines = 1\n        )\n    }\n}\n'

s = s[:start] + replacement + s[end:]
p.write_text(s, encoding="utf-8")
print("No.010 applied:", p)
